content:
430          aMessage.Write(0, sizeof(ip6Header), &ip6Header);
   431      }
   432      else if (mplOffset != 0)
   433      {
   434          // replace MPL Option with PadN Option
   435          OptionPadN padOption;
   436
   437          padOption.Init(sizeof(OptionHeader) + mplLength);
   438          aMessage.Write(mplOffset, padOption.GetTotalLength(), &padOption);
   439      }
   440
   441  exit:
   442      return error;
   443  }
